mapper.select:
SELECT u.id, u.username, u.persona_id, u.bloqueado, u.activo, u.created_at, u.updated_at, u.deleted, u.version, p.nombre AS p_nombre, p.primer_apellido AS p_primer_apellido, p.segundo_apellido AS p_segundo_apellido, p.ci AS p_ci, p.email AS p_email FROM usuario u LEFT JOIN persona p ON p.id = u.persona_id AND p.deleted = FALSE
u.deleted = FALSE AND u.username ILIKE '%' || #{username} '%' AND (p.nombre ILIKE '%' || #{personaNombre} '%' OR p.primer_apellido ILIKE '%' || #{personaNombre} '%')
ORDER BY u.created_at DESC LIMIT #{limit} OFFSET #{offset}
